// Multi-dimensional re-score of the competence benchmark, defining "top 1%" as strength across SIX
// competencies, not just knowledge. Reuses the answers already generated by eval-all-roles-competence.ts
// (no regeneration), and has a blind cross-model Groq judge score each saved answer on all 6 dimensions,
// RAG off vs on. Groups the dimensions into knowledge-dependent (RAG should lift) vs reasoning-dependent
// (RAG should barely move) as a built-in bias check.
//
// Run: LLM_MODE=prod ./node_modules/.bin/tsx -r dotenv/config scripts/eval-competence-dimensions.ts
import { readFileSync, writeFileSync, existsSync } from 'fs';
import { QUESTIONS } from './eval-all-roles-competence.js';
import { generateWithPreferredProvider } from '../server/llm/providerResolver.js';

const IN = '/private/tmp/claude-501/-Users-shashankrai-Documents-hatching-mvp-5th-march/e433eb83-3933-4614-80d6-c592aed4b0f7/scratchpad/competence-results.json';
const OUT = '/private/tmp/claude-501/-Users-shashankrai-Documents-hatching-mvp-5th-march/e433eb83-3933-4614-80d6-c592aed4b0f7/scratchpad/competence-dimensions.json';
const EVAL_PROVIDER = (process.env.EVAL_PROVIDER || (process.env.GROQ_API_KEY ? 'groq' : 'gemini')) as any;
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

const DIMS = ['knowledge', 'diagnosis', 'application', 'judgment', 'creativity', 'rigor'] as const;
const KNOWLEDGE_DEP = ['knowledge', 'application', 'rigor']; // RAG should lift these
const REASONING_DEP = ['diagnosis', 'judgment', 'creativity']; // RAG should barely move these

async function scoreDims(q: any, answer: string): Promise<Record<string, number>> {
  const system =
    'You are a senior examiner rating one expert answer from a working professional in a chat (concise is fine, do NOT ' +
    'penalize brevity). Rate 1-5 on SIX independent competencies of a TOP 1% practitioner:\n' +
    'knowledge: commands the field canon (correct frameworks/methods/benchmarks) AND its failure modes.\n' +
    'diagnosis: correctly reads and frames the REAL problem before solutioning.\n' +
    'application: applies the RIGHT method to THIS specific situation with concrete, correct, actionable specifics (not just naming it).\n' +
    'judgment: makes the hard trade-off, sequences, cuts what does not matter, realistic about constraints.\n' +
    'creativity: brings a non-obvious insight, reframe, or second-order point beyond a competent-average answer.\n' +
    'rigor: backs claims, cites or admits uncertainty, avoids overclaiming.\n' +
    '5 = top-1% on that competency; 3 = competent/generic; 1 = absent/wrong. Score each independently. ' +
    'Return ONLY JSON: {"knowledge":n,"diagnosis":n,"application":n,"judgment":n,"creativity":n,"rigor":n}.';
  const user = `Question: ${q.q}\n\nReference (expert canon for this field): ${q.rubric}\n\nAnswer:\n${answer}\n\nJSON:`;
  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      const c = await generateWithPreferredProvider(
        { messages: [{ role: 'system', content: system }, { role: 'user', content: user }], temperature: 0, maxTokens: 160 } as any,
        EVAL_PROVIDER,
      );
      const m = (c.content || '').match(/\{[\s\S]*\}/);
      if (!m) { await sleep(1500); continue; }
      const p = JSON.parse(m[0]);
      const out: Record<string, number> = {};
      for (const d of DIMS) out[d] = Number(p[d]) || 0;
      return out;
    } catch { await sleep(2000); }
  }
  return Object.fromEntries(DIMS.map((d) => [d, 0]));
}

async function main() {
  if (!existsSync(IN)) { console.error('No competence-results.json; run eval-all-roles-competence.ts first.'); process.exit(1); }
  const answers = JSON.parse(readFileSync(IN, 'utf8'));
  const qByRole = new Map(QUESTIONS.map((q) => [q.role, q]));
  const results: any[] = existsSync(OUT) ? JSON.parse(readFileSync(OUT, 'utf8')) : [];
  const done = new Set(results.map((r) => r.role));
  console.log(`Multi-dimensional re-score, ${answers.length} roles. Judge: ${EVAL_PROVIDER}. Done: ${done.size}.\n`);
  for (const row of answers) {
    if (done.has(row.role)) { console.log(`  [skip] ${row.role}`); continue; }
    const q = qByRole.get(row.role); if (!q) continue;
    try {
      const off = await scoreDims(q, row.aOff); await sleep(400);
      const on = await scoreDims(q, row.aOn); await sleep(400);
      results.push({ role: row.role, off, on });
      writeFileSync(OUT, JSON.stringify(results, null, 2));
      const line = DIMS.map((d) => `${d[0]}${off[d]}→${on[d]}`).join(' ');
      console.log(`  [${row.role.padEnd(24)}] ${line}`);
    } catch (e: any) { console.log(`  [${row.role}] ERROR ${e?.message || e}`); }
  }
  const s = results;
  const avg = (mode: 'off' | 'on', d: string) => s.reduce((a, r) => a + (r[mode][d] || 0), 0) / (s.length || 1);
  console.log(`\n=== ${s.length} roles · per-dimension average (RAG off → on) ===`);
  let kOff = 0, kOn = 0, rOff = 0, rOn = 0;
  for (const d of DIMS) {
    const o = avg('off', d), n = avg('on', d);
    const grp = KNOWLEDGE_DEP.includes(d) ? 'knowledge-dep' : 'reasoning-dep';
    console.log(`  ${d.padEnd(12)} ${o.toFixed(2)} → ${n.toFixed(2)}   (${(n - o >= 0 ? '+' : '')}${(n - o).toFixed(2)})   [${grp}]`);
    if (KNOWLEDGE_DEP.includes(d)) { kOff += o; kOn += n; } else { rOff += o; rOn += n; }
  }
  console.log(`\n  Knowledge-dependent group: ${(kOff / 3).toFixed(2)} → ${(kOn / 3).toFixed(2)}  (${(kOn / 3 - kOff / 3 >= 0 ? '+' : '')}${(kOn / 3 - kOff / 3).toFixed(2)})  <- RAG should lift this`);
  console.log(`  Reasoning-dependent group: ${(rOff / 3).toFixed(2)} → ${(rOn / 3).toFixed(2)}  (${(rOn / 3 - rOff / 3 >= 0 ? '+' : '')}${(rOn / 3 - rOff / 3).toFixed(2)})  <- RAG should barely move this (bias check)`);
  const top1 = s.filter((r) => DIMS.every((d) => r.on[d] >= 4)).length;
  console.log(`\n  Roles top-1% on ALL 6 dimensions (every dim >=4 with RAG on): ${top1}/${s.length}`);
  console.log(`Results saved: ${OUT}`);
  process.exit(0);
}
main().catch((e) => { console.error('ERROR:', e?.message || e); process.exit(1); });
